internal delegate T TdfPayloadStructReader<T>(ref TdfPayloadReader reader);

internal ref struct TdfPayloadReader
{
    private readonly ReadOnlySpan<byte> data;
    private int offset;

    internal TdfPayloadReader(ReadOnlySpan<byte> data)
    {
        this.data = data;
    }

    internal void EnsureConsumed()
    {
        if (offset != data.Length)
        {
            throw new ArgumentException("Payload contains trailing bytes.", nameof(data));
        }
    }

    internal byte ReadByte()
    {
        EnsureAvailable(1);
        return data[offset++];
    }

    internal sbyte ReadSByte()
    {
        return unchecked((sbyte)ReadByte());
    }

    internal char ReadChar()
    {
        return (char)ReadByte();
    }

    internal short ReadInt16()
    {
        return unchecked((short)ReadUInt16());
    }

    internal ushort ReadUInt16()
    {
        EnsureAvailable(2);
        var value = (ushort)(data[offset] | (data[offset + 1] << 8));
        offset += 2;
        return value;
    }

    internal int ReadInt32()
    {
        return unchecked((int)ReadUInt32());
    }

    internal uint ReadUInt32()
    {
        EnsureAvailable(4);
        var value = (uint)(data[offset] | (data[offset + 1] << 8) | (data[offset + 2] << 16) | (data[offset + 3] << 24));
        offset += 4;
        return value;
    }

    internal ulong ReadUInt64()
    {
        var lo = ReadUInt32();
        var hi = ReadUInt32();
        return lo | ((ulong)hi << 32);
    }

    internal ulong ReadUInt(int count, bool littleEndian)
    {
        if (count < 0 || count > 8)
        {
            throw new ArgumentOutOfRangeException(nameof(count), "Integer byte count must be between 0 and 8.");
        }

        EnsureAvailable(count);
        ulong value = 0;
        for (var i = 0; i < count; i++)
        {
            var sourceIndex = littleEndian ? offset + i : offset + count - 1 - i;
            value |= (ulong)data[sourceIndex] << (8 * i);
        }

        offset += count;
        return value;
    }

    internal float ReadSingle()
    {
        var bytes = ReadByteArray(4);
        if (!BitConverter.IsLittleEndian)
        {
            Array.Reverse(bytes);
        }

        return BitConverter.ToSingle(bytes, 0);
    }

    internal string ReadString(int count)
    {
        return Encoding.ASCII.GetString(ReadByteArray(count)).TrimEnd('\0');
    }

    internal string ReadRemainingString()
    {
        return Encoding.ASCII.GetString(ReadByteArray(data.Length - offset)).TrimEnd('\0');
    }

    internal IReadOnlyList<byte> ReadBytes(int count)
    {
        return Array.AsReadOnly(ReadByteArray(count));
    }

    internal IReadOnlyList<byte> ReadRemainingBytes()
    {
        return Array.AsReadOnly(ReadByteArray(data.Length - offset));
    }

    private byte[] ReadByteArray(int count)
    {
        EnsureAvailable(count);
        var bytes = new byte[count];
        data.Slice(offset, count).CopyTo(bytes);
        offset += bytes.Length;
        return bytes;
    }

    internal sbyte[] ReadSByteValues(int count)
    {
        var values = new sbyte[count];
        for (var i = 0; i < count; i++)
        {
            values[i] = ReadSByte();
        }

        return values;
    }

    internal sbyte[] ReadRemainingSByteValues(int elementSize)
    {
        return ReadSByteValues(GetRemainingElementCount(elementSize));
    }

    internal short[] ReadInt16Values(int count)
    {
        var values = new short[count];
        for (var i = 0; i < count; i++)
        {
            values[i] = ReadInt16();
        }

        return values;
    }

    internal short[] ReadRemainingInt16Values(int elementSize)
    {
        return ReadInt16Values(GetRemainingElementCount(elementSize));
    }

    internal ushort[] ReadUInt16Values(int count)
    {
        var values = new ushort[count];
        for (var i = 0; i < count; i++)
        {
            values[i] = ReadUInt16();
        }

        return values;
    }

    internal ushort[] ReadRemainingUInt16Values(int elementSize)
    {
        return ReadUInt16Values(GetRemainingElementCount(elementSize));
    }

    internal int[] ReadInt32Values(int count)
    {
        var values = new int[count];
        for (var i = 0; i < count; i++)
        {
            values[i] = ReadInt32();
        }

        return values;
    }

    internal int[] ReadRemainingInt32Values(int elementSize)
    {
        return ReadInt32Values(GetRemainingElementCount(elementSize));
    }

    internal uint[] ReadUInt32Values(int count)
    {
        var values = new uint[count];
        for (var i = 0; i < count; i++)
        {
            values[i] = ReadUInt32();
        }

        return values;
    }

    internal uint[] ReadRemainingUInt32Values(int elementSize)
    {
        return ReadUInt32Values(GetRemainingElementCount(elementSize));
    }

    internal ulong[] ReadUInt64Values(int count)
    {
        var values = new ulong[count];
        for (var i = 0; i < count; i++)
        {
            values[i] = ReadUInt64();
        }

        return values;
    }

    internal ulong[] ReadRemainingUInt64Values(int elementSize)
    {
        return ReadUInt64Values(GetRemainingElementCount(elementSize));
    }

    internal float[] ReadSingleValues(int count)
    {
        var values = new float[count];
        for (var i = 0; i < count; i++)
        {
            values[i] = ReadSingle();
        }

        return values;
    }

    internal float[] ReadRemainingSingleValues(int elementSize)
    {
        return ReadSingleValues(GetRemainingElementCount(elementSize));
    }

    internal T[] ReadStructs<T>(int count, TdfPayloadStructReader<T> read)
    {
        var values = new T[count];
        for (var i = 0; i < count; i++)
        {
            values[i] = read(ref this);
        }

        return values;
    }

    internal T[] ReadRemainingStructs<T>(TdfPayloadStructReader<T> read)
    {
        var values = new List<T>();
        while (offset < data.Length)
        {
            values.Add(read(ref this));
        }

        return values.ToArray();
    }

    private int GetRemainingElementCount(int elementSize)
    {
        if (elementSize <= 0 || (data.Length - offset) % elementSize != 0)
        {
            throw new ArgumentException("Payload length is not valid for the requested element size.", nameof(data));
        }

        return (data.Length - offset) / elementSize;
    }

    private void EnsureAvailable(int length)
    {
        if (length < 0 || offset + length > data.Length)
        {
            throw new ArgumentException("Payload is shorter than the target type requires.", nameof(data));
        }
    }
}
